		uint32_t k1 = 0;

		switch (len & 3) {
		case 3: k1 ^= tail[2] << 16; JEMALLOC_FALLTHROUGH;
		case 2: k1 ^= tail[1] << 8; JEMALLOC_FALLTHROUGH;
		case 1: k1 ^= tail[0]; k1 *= c1; k1 = hash_rotl_32(k1, 15);
			k1 *= c2; h1 ^= k1;
		}
	}

	/* finalization */
	h1 ^= len;

	h1 = hash_fmix_32(h1);

	return h1;
